-- composition of rule kernels L:decorrelate_predicate_subquery x L:replace_distinct_aggregate (datafusion), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT make_array(NULL, 1) AS c0, '-3 hours'::interval AS c1 FROM t2 AS a1 GROUP BY a1.c2 HAVING (ARRAY[1, 2, 3] IN (SELECT ARRAY[1] AS c0))) AS ka UNION ALL SELECT 2 AS k FROM (SELECT '2000-01-01'::date AS c0, 'NaN'::text AS c1 UNION SELECT '1999-12-31'::date AS c0, 'abc'::text AS c1) AS kb) AS u;
